import { motion } from "framer-motion";
import { Shield, Activity, BookOpen, LogOut, Scan } from "lucide-react";
import { useAuth } from "@/contexts/AuthContext";

// Removed sounds import

export type DashboardPage = "dashboard" | "analyze" | "ledger";

interface NavbarProps {
  currentPage: DashboardPage;
  onNavigate: (page: DashboardPage) => void;
}

const tabs: ReadonlyArray<readonly [DashboardPage, string, typeof Activity]> = [
  ["dashboard", "Dashboard", Activity],
  ["analyze", "Analyze", Scan],
  ["ledger", "Ledger", BookOpen],
];

export default function Navbar({ currentPage, onNavigate }: NavbarProps) {
  const { signOut, user } = useAuth();

  const handleNav = (page: DashboardPage) => {
    onNavigate(page);
  };

  return (
    <motion.nav
      initial={{ y: -20, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      className="glass-strong sticky top-0 z-40 px-6 py-4"
    >
      <div className="max-w-7xl mx-auto flex items-center justify-between gap-4 flex-wrap">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg gradient-primary flex items-center justify-center neon-glow">
            <Shield size={20} className="text-primary-foreground" />
          </div>
          <div>
            <h1 className="font-display font-bold text-lg text-gradient">FraudShield</h1>
            <p className="text-xs text-muted-foreground">AI-Powered Detection</p>
          </div>
        </div>

        <div className="flex gap-1 bg-muted/50 rounded-lg p-1">
          {tabs.map(([key, label, Icon]) => (
            <motion.button
              key={key}
              onClick={() => handleNav(key)}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
              className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                currentPage === key
                  ? "gradient-primary text-primary-foreground neon-glow"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              <Icon size={16} />
              <span className="hidden sm:inline">{label}</span>
            </motion.button>
          ))}
        </div>

        <div className="flex items-center gap-3">
          <span className="text-xs text-muted-foreground hidden md:block">{user?.email}</span>
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={() => {
              if (typeof window !== 'undefined') localStorage.removeItem('authenticated');
              void signOut();
            }}
            className="flex items-center gap-1 px-3 py-2 rounded-lg text-sm text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-all cursor-pointer"
          >
            <LogOut size={16} /> <span className="hidden sm:inline">Sign Out</span>
          </motion.button>
        </div>
      </div>
    </motion.nav>
  );
}
