import { Line, Doughnut } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  ArcElement,
  Filler,
} from "chart.js";
import { motion } from "framer-motion";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, ArcElement, Filler);

interface FraudChartProps {
  safeCount: number;
  suspiciousCount: number;
  fraudCount: number;
  dailyData: { date: string; fraud: number; safe: number }[];
}

export default function FraudChart({ safeCount, suspiciousCount, fraudCount, dailyData }: FraudChartProps) {
  const doughnutData = {
    labels: ["Safe", "Suspicious", "Fraud"],
    datasets: [
      {
        data: [safeCount, suspiciousCount, fraudCount],
        backgroundColor: ["rgba(56, 224, 199, 0.85)", "rgba(245, 180, 70, 0.85)", "rgba(240, 80, 90, 0.85)"],
        borderColor: "transparent",
        borderWidth: 0,
      },
    ],
  };

  const lineData = {
    labels: dailyData.map((d) => d.date),
    datasets: [
      {
        label: "Fraud",
        data: dailyData.map((d) => d.fraud),
        borderColor: "rgb(240, 80, 90)",
        backgroundColor: "rgba(240, 80, 90, 0.12)",
        fill: true,
        tension: 0.4,
        pointBackgroundColor: "rgb(240, 80, 90)",
        pointRadius: 4,
      },
      {
        label: "Safe",
        data: dailyData.map((d) => d.safe),
        borderColor: "rgb(56, 224, 199)",
        backgroundColor: "rgba(56, 224, 199, 0.12)",
        fill: true,
        tension: 0.4,
        pointBackgroundColor: "rgb(56, 224, 199)",
        pointRadius: 4,
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { labels: { color: "rgb(190, 195, 220)", font: { family: "Inter" } } },
    },
    scales: {
      x: { ticks: { color: "rgb(140, 145, 170)" }, grid: { color: "rgba(220, 220, 240, 0.05)" } },
      y: { ticks: { color: "rgb(140, 145, 170)" }, grid: { color: "rgba(220, 220, 240, 0.05)" } },
    },
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
      <motion.div
        initial={{ opacity: 0, x: -20 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ duration: 0.6, delay: 0.4 }}
        className="lg:col-span-2 glass rounded-xl p-6"
      >
        <h3 className="text-lg font-display font-semibold mb-4">Fraud Trends (7 Days)</h3>
        <div className="h-64">
          <Line data={lineData} options={chartOptions} />
        </div>
      </motion.div>
      <motion.div
        initial={{ opacity: 0, x: 20 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ duration: 0.6, delay: 0.5 }}
        className="glass rounded-xl p-6"
      >
        <h3 className="text-lg font-display font-semibold mb-4">Distribution</h3>
        <div className="h-64 flex items-center justify-center">
          <Doughnut
            data={doughnutData}
            options={{
              responsive: true,
              maintainAspectRatio: false,
              plugins: {
                legend: { position: "bottom", labels: { color: "rgb(190, 195, 220)", padding: 16, font: { family: "Inter" } } },
              },
              cutout: "65%",
            }}
          />
        </div>
      </motion.div>
    </div>
  );
}
