import { motion, AnimatePresence } from "framer-motion";
import { ShieldAlert, X } from "lucide-react";
import { useEffect } from "react";

interface FraudAlertProps {
  message: string | null;
  onClose: () => void;
}

export default function FraudAlert({ message, onClose }: FraudAlertProps) {
  useEffect(() => {
    if (!message) return;
    const t = setTimeout(onClose, 5000);
    return () => clearTimeout(t);
  }, [message, onClose]);

  return (
    <AnimatePresence>
      {message && (
        <motion.div
          initial={{ opacity: 0, x: 300 }}
          animate={{ opacity: 1, x: 0 }}
          exit={{ opacity: 0, x: 300 }}
          className="fixed top-6 right-6 z-[100] max-w-sm"
        >
          <div className="glass-strong rounded-xl p-4 border border-destructive/40 flex items-start gap-3">
            <motion.div
              animate={{ scale: [1, 1.2, 1] }}
              transition={{ duration: 0.5, repeat: 3 }}
              className="p-2 rounded-lg bg-destructive/20 flex-shrink-0"
            >
              <ShieldAlert size={20} className="text-destructive" />
            </motion.div>
            <div className="flex-1">
              <p className="font-display font-bold text-sm text-destructive">Fraud Alert!</p>
              <p className="text-xs text-muted-foreground mt-1">{message}</p>
            </div>
            <button onClick={onClose} className="text-muted-foreground hover:text-foreground transition-colors">
              <X size={16} />
            </button>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}
