import { motion } from "framer-motion";
import type { LucideIcon } from "lucide-react";

interface StatCardProps {
  title: string;
  value: string | number;
  icon: LucideIcon;
  trend?: string;
  variant: "purple" | "blue" | "cyan" | "danger";
  delay?: number;
}

const tone: Record<StatCardProps["variant"], { bg: string; icon: string; text: string }> = {
  purple: { bg: "bg-neon-purple/10 border-neon-purple/25", icon: "bg-neon-purple/20 text-neon-purple", text: "text-neon-purple" },
  blue:   { bg: "bg-neon-blue/10 border-neon-blue/25",     icon: "bg-neon-blue/20 text-neon-blue",     text: "text-neon-blue"   },
  cyan:   { bg: "bg-neon-cyan/10 border-neon-cyan/25",     icon: "bg-neon-cyan/20 text-neon-cyan",     text: "text-neon-cyan"   },
  danger: { bg: "bg-destructive/10 border-destructive/25", icon: "bg-destructive/20 text-destructive", text: "text-destructive" },
};

export default function StatCard({ title, value, icon: Icon, trend, variant, delay = 0 }: StatCardProps) {
  const t = tone[variant];
  return (
    <motion.div
      initial={{ opacity: 0, y: 30 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6, delay, ease: "easeOut" }}
      whileHover={{ y: -6, transition: { duration: 0.2 } }}
      className={`glass rounded-xl p-6 border ${t.bg}`}
    >
      <div className="flex items-start justify-between gap-4">
        <div className="min-w-0">
          <p className="text-sm text-muted-foreground mb-1">{title}</p>
          <motion.p
            className="text-3xl font-display font-bold"
            initial={{ scale: 0.6 }}
            animate={{ scale: 1 }}
            transition={{ duration: 0.4, delay: delay + 0.2, type: "spring" }}
          >
            {value}
          </motion.p>
          {trend && <p className="text-xs text-muted-foreground mt-2">{trend}</p>}
        </div>
        <div className={`p-3 rounded-lg ${t.icon}`}>
          <Icon size={22} />
        </div>
      </div>
    </motion.div>
  );
}
