import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { BookOpen, Download, Filter, IndianRupee, ShieldAlert, ShieldCheck, AlertTriangle } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import GlassCard from "./GlassCard";

interface LedgerEntry {
  id: string;
  transaction_id: string;
  amount: number;
  location: string;
  user_behavior: string | null;
  fraud_score: number;
  status: "safe" | "suspicious" | "fraud";
  analyzed_at: string;
}

const statusConfig = {
  safe:       { Icon: ShieldCheck,   color: "text-success",     bg: "bg-success/10",     badge: "bg-success/15 text-success border-success/25" },
  suspicious: { Icon: AlertTriangle, color: "text-warning",     bg: "bg-warning/10",     badge: "bg-warning/15 text-warning border-warning/25" },
  fraud:      { Icon: ShieldAlert,   color: "text-destructive", bg: "bg-destructive/10", badge: "bg-destructive/15 text-destructive border-destructive/25" },
} as const;

export default function TransactionLedger() {
  const { user } = useAuth();
  const [entries, setEntries] = useState<LedgerEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<"all" | "safe" | "suspicious" | "fraud">("all");

  useEffect(() => {
    if (!user) return;
    let mounted = true;

    (async () => {
      setLoading(true);
      const { data } = await supabase
        .from("transaction_ledger")
        .select("*")
        .order("analyzed_at", { ascending: false });
      if (mounted && data) setEntries(data as LedgerEntry[]);
      if (mounted) setLoading(false);
    })();

    const channel = supabase
      .channel("ledger-changes")
      .on(
        "postgres_changes",
        { event: "INSERT", schema: "public", table: "transaction_ledger" },
        (payload) => setEntries((prev) => [payload.new as LedgerEntry, ...prev]),
      )
      .subscribe();

    return () => {
      mounted = false;
      void supabase.removeChannel(channel);
    };
  }, [user]);

  const filtered = filter === "all" ? entries : entries.filter((e) => e.status === filter);

  const totals = {
    total: entries.length,
    totalAmount: entries.reduce((s, e) => s + Number(e.amount), 0),
    safe: entries.filter((e) => e.status === "safe").length,
    fraud: entries.filter((e) => e.status === "fraud").length,
  };

  const exportCSV = () => {
    const headers = "Transaction ID,Amount (INR),Location,Behavior,Fraud Score,Status,Analyzed At\n";
    const rows = filtered
      .map((e) =>
        `${e.transaction_id},${e.amount},${e.location},${e.user_behavior || "N/A"},${e.fraud_score}%,${e.status},${new Date(e.analyzed_at).toLocaleString("en-IN")}`,
      )
      .join("\n");
    const blob = new Blob([headers + rows], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `fraud-ledger-${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <motion.div
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: -20 }}
      transition={{ duration: 0.3 }}
      className="space-y-6"
    >
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div>
          <h2 className="text-3xl font-display font-bold text-gradient mb-2">Transaction Ledger</h2>
          <p className="text-muted-foreground">Complete register of all analyzed transactions</p>
        </div>
        <motion.button
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          onClick={exportCSV}
          className="flex items-center gap-2 px-4 py-2 rounded-lg gradient-primary text-primary-foreground text-sm font-medium"
        >
          <Download size={16} /> Export CSV
        </motion.button>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <GlassCard delay={0.1} className="!p-4">
          <p className="text-xs text-muted-foreground">Total Analyzed</p>
          <p className="text-2xl font-display font-bold">{totals.total}</p>
        </GlassCard>
        <GlassCard delay={0.15} className="!p-4">
          <p className="text-xs text-muted-foreground">Total Volume</p>
          <p className="text-2xl font-display font-bold flex items-center gap-1">
            <IndianRupee size={18} />{totals.totalAmount.toLocaleString("en-IN")}
          </p>
        </GlassCard>
        <GlassCard delay={0.2} className="!p-4">
          <p className="text-xs text-muted-foreground">Safe Rate</p>
          <p className="text-2xl font-display font-bold text-success">
            {totals.total > 0 ? ((totals.safe / totals.total) * 100).toFixed(1) : 0}%
          </p>
        </GlassCard>
        <GlassCard delay={0.25} className="!p-4">
          <p className="text-xs text-muted-foreground">Fraud Rate</p>
          <p className="text-2xl font-display font-bold text-destructive">
            {totals.total > 0 ? ((totals.fraud / totals.total) * 100).toFixed(1) : 0}%
          </p>
        </GlassCard>
      </div>

      <div className="flex items-center gap-2 flex-wrap">
        <Filter size={16} className="text-muted-foreground" />
        {(["all", "safe", "suspicious", "fraud"] as const).map((f) => (
          <button
            key={f}
            onClick={() => setFilter(f)}
            className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
              filter === f ? "gradient-primary text-primary-foreground" : "bg-muted/50 text-muted-foreground hover:text-foreground"
            }`}
          >
            {f.charAt(0).toUpperCase() + f.slice(1)} {f !== "all" && `(${entries.filter((e) => e.status === f).length})`}
          </button>
        ))}
      </div>

      {loading ? (
        <div className="space-y-3">
          {Array.from({ length: 5 }).map((_, i) => (
            <div key={i} className="glass rounded-xl p-4 animate-pulse">
              <div className="h-4 bg-muted rounded w-1/3 mb-2" />
              <div className="h-3 bg-muted rounded w-2/3" />
            </div>
          ))}
        </div>
      ) : filtered.length === 0 ? (
        <GlassCard hover={false} className="text-center py-12">
          <BookOpen size={48} className="mx-auto text-muted-foreground mb-4" />
          <p className="text-lg font-display font-semibold">No entries yet</p>
          <p className="text-sm text-muted-foreground mt-1">
            {entries.length === 0
              ? "Analyze transactions to start building your ledger"
              : "No transactions match the selected filter"}
          </p>
        </GlassCard>
      ) : (
        <div className="space-y-2">
          {filtered.map((entry, i) => {
            const cfg = statusConfig[entry.status];
            const Icon = cfg.Icon;
            return (
              <motion.div
                key={entry.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.03, duration: 0.3 }}
                className="glass rounded-xl p-4 hover:bg-muted/20 transition-colors"
              >
                <div className="flex items-center gap-4 flex-wrap">
                  <div className={`p-2 rounded-lg ${cfg.bg} flex-shrink-0`}>
                    <Icon size={20} className={cfg.color} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1 flex-wrap">
                      <span className="font-mono text-sm font-semibold">{entry.transaction_id}</span>
                      <span className={`px-2 py-0.5 text-[10px] font-bold rounded-full border ${cfg.badge}`}>
                        {entry.status.toUpperCase()}
                      </span>
                    </div>
                    <p className="text-xs text-muted-foreground">
                      {entry.location} · {new Date(entry.analyzed_at).toLocaleString("en-IN")}
                    </p>
                  </div>
                  <div className="text-right">
                    <p className="font-display font-bold">₹{Number(entry.amount).toLocaleString("en-IN")}</p>
                    <p className="text-xs text-muted-foreground font-mono">Score: {entry.fraud_score}%</p>
                  </div>
                </div>
              </motion.div>
            );
          })}
        </div>
      )}
    </motion.div>
  );
}
